-- =====================================================================
-- Mesa Gourmet · Datos iniciales y ajustes (ejecutar UNA vez, después de schema.sql)
-- Supabase > SQL Editor > New query > pegar todo > Run
-- Carga La Cocina de Ramsés, Carlota y ¡Que Empanadas! con sus cartas y los datos públicos de la encuesta.
-- No incluye reseñas, promociones ni destacados de ejemplo: esos los crean los usuarios y tú desde el panel.
-- =====================================================================

-- Columnas que la app usa y faltaban en el esquema
alter table public.locales add column if not exists carta_url text;
alter table public.locales add column if not exists whatsapp_reservas text;

-- El panel asigna el número de cada local nuevo, así que los ids se pueden indicar al crear
alter table public.locales alter column id set generated by default;

insert into public.locales (id, nombre, tipo, slogan, direccion, referencia, nota_acceso, telefono, whatsapp, whatsapp_reservas, instagram, tiktok, facebook, website, carta_url, descripcion, imagen_url, lat, lng, horarios, horario_feriados, medios_pago, capacidad, ambiente, tematica, horas_peak, dias_peak, caracteristicas, caracteristicas_detalle, etiquetas)
values (1, 'La Cocina de Ramsés', 'Restaurante Peruano', null, '1 Sur, 3 Poniente, Talca', 'Cerca de la Iglesia Pompeya, la Escuela de Profesores y la Plaza de Armas', null, '+56 71 222 3612', '56933887553', null, 'lacocinaderamses', null, 'La Cocina de Ramsés', null, 'https://uqr.to/LaCocinadeRamsesCartaDigital', 'Auténtica gastronomía peruana en el corazón de Talca. Sabores tradicionales preparados por expertos chefs.', 'locales/ramses.jpg', -35.415, -71.66, '{"Lunes":"13:00 - 22:45","Martes":"13:00 - 22:45","Miércoles":"13:00 - 22:45","Jueves":"13:00 - 23:45","Viernes":"13:00 - 23:45","Sábado":"13:00 - 23:45","Domingo":"13:00 - 17:30"}'::jsonb, 'Abre el 18 de septiembre, Navidad, Año Nuevo y Día del Trabajador, con el horario normal', 'Tarjeta, efectivo y transferencia', '30 mesas', 'Adultos y adultos mayores', 'Cultura peruana', '13:00 a 16:00 y 20:00 a 23:00', 'Jueves a domingo', array['Baño / WC', 'WiFi Disponible', 'Terraza', 'Mascotas (Solo en Terraza)', 'Aire Acondicionado / Ventilación', 'Acceso Discapacitados', 'Estacionamiento', 'Venta de Alcohol', 'Apto para Fumadores (Solo en Terraza)', 'Apto para menores de edad', 'Acepta reservas', 'Arriendo para eventos', 'Barra', 'Bicicletero', 'Consumo en el local']::text[], '{"Venta de Alcohol":"Tragos preparados, cerveza y vino","Acepta reservas":"Al +56 71 222 3612","Arriendo para eventos":"Sector privado para 10 a 12 personas, o el local completo","Estacionamiento":"6 espacios en estacionamiento y en la vereda","Bicicletero":"No hay bicicletero, pero se puede dejar en la terraza","Baño / WC":"No adaptado para silla de ruedas"}'::jsonb, array['peruano', 'ceviche', 'mariscos', 'pisco']::text[])
on conflict (id) do nothing;

