insert into public.platos (local_id, nombre, categoria, precio, imagen_url, es_bebida, dietas, orden)
select * from (values
  (3::bigint, 'Empanada de Pino Horno', 'Empanadas', 2200, 'https://images.unsplash.com/photo-1604467715878-83e57e8bc129?w=400&h=400&fit=crop', false, array['sinLactosa']::text[], 0),
